'use client';

// ============================================================
// cmem timeline viewer — session card (alt chrome, Phase 1).
// Canonical anatomy from the alt card, dc.html 376–682 / SPEC
// §6, in natural DOM order (no CSS `order:` juggling):
//
//   section.tcv-session
//     div.tcv-tinthead[data-face]  — single tinted head:
//       arc rings → head row (cross-fade label stack + settled
//       time-range/badge/segmented control, or the live eye
//       counter + pill) → title cross-fade (h2 summary / quoted
//       prompt, 320ms) → collapsing summary body (grid-rows
//       1fr/0fr, 480ms).
//     div.tcv-railwrap[data-open]  — grid-rows collapse pair
//       around the full-bleed rail: expanded on the prompt face
//       (and always for no-summary sessions), collapsed on the
//       summary face. onTransitionEnd → onRailReveal so the
//       ruler bands re-sync after the 480ms expand.
//
// Faces (data-face, butter summary / lilac prompt — dc.html
// 2130–2143): `summary` when the session has a summary, `prompt`
// otherwise or via the segmented control. No-summary sessions
// hold a permanent prompt face — the old dashed .tcv-distill
// placeholder no longer renders.
//
// Head-row right region (Phase 3, dc.html 394–422): while `live`
// the streaming region renders — eye counter (hidden at 0) +
// Recording pill; freshly wrapped without a summary (< 5 min past
// `ended`, on the 20s clock) the distilling region renders —
// time-range + spinner pill with the real obs count; otherwise
// the settled region — time-range + count badge (+ seg control
// only when the session can toggle, so settled-no-summary
// sessions show the badge alone).
//
// Obs face (Phase 2, plan mapping decision #1–2 — not in the dc
// design): clicking a rail obs card (toggle) or ruler dot swaps
// the head to that observation. Face derives from the selection:
// selected → `obs` (lilac, the working-face family), else the
// Phase 1 summary/prompt logic. On the obs face the head shows
// the shrunken prompt row (avatar + 1-line quote + `prompt ·
// time`; click = back to prompt), the obs title in the headline
// cross-fade slot, a type-chip meta row, and facts + a narrative
// expander in the same collapsing body slot the summary rows use.
// Deselect paths: shrunken prompt row, either seg button (both
// render unpressed on the obs face), or re-clicking the selected
// card. Ruler-dot selection deliberately adds NO jump — the
// document-delegated [data-dot] handler in useRailSync already
// centers + flashes.
//
// Live cycle (Phase 3, plan mapping decision #4): while recording
// with `follow` on, every newly-landed observation auto-takes the
// selection (derived-state on the newest obs id — the first
// landing swaps the full-size prompt to the obs face, i.e. the
// prompt "shrinks"). Clicking a non-newest obs pins (follow off,
// landings stop stealing); clicking the newest resumes following.
// The wrap (live→false with a summary) clears the selection and
// lands the butter summary face with the tcv-hero--landed
// entrance. No timers here — real props + the shared 20s clock
// drive everything.
//
// Live variant (DESIGN-SPEC §7): the ruler window extends to a
// 20s-ticked wall clock, a playhead tracks now, the strip
// appends the "now" watching slot, and landings animate via the
// section's data-live attribute. When the session wraps the
// summary face lands with a tcFadeUp entrance.
//
// Type stacks (Phase 4, dc.html 444–521): the summary face renders
// per-type observation stacks after the summary rows — inside the
// same collapsing body, so they collapse with it on other faces.
// TYPE_META key order, unknown types trailing with the neutral
// chip fallback ObsCard/Ruler use; a "stacked paper" back layer
// appears at count ≥ 2. Clicking (or Enter/Space) selects that
// type's EARLIEST observation; the face change expands the rail,
// and the center+flash jump fires only once the 480ms grid-rows
// expand settles — the pending domId parks in a ref and the
// railwrap transitionend below invokes onObsReveal (wired to
// rail.jumpToObs), replacing the design's 540ms altGoToObs timer
// (dc.html 1774–1777) with the real transition boundary. The ✦
// magic button + KINDSUM panel are omitted (plan mapping
// decision #5).
// ============================================================
import * as React from 'react';

import { ChevronDown, Eye } from 'lucide-react';

import type { VObservation, VPrompt, VSession } from './types';

import { Ruler } from './Ruler';
import { Strip } from './Strip';
import { TYPE_META, fmtTime } from './format';
import { fmtTimeRange, fracFor, rulerWindow } from './timeline-data';

// ---------- shared 20s wall clock (lint-safe: no Date.now() in render) ----------
// One module-level interval feeds every subscribed card via
// useSyncExternalStore; the snapshot is quantized to 20s so it is
// referentially stable between ticks (plan Phase 4: production
// playhead ticks ~20s, `left 460ms linear` smooths the hop).
const clockListeners = new Set<() => void>();
let clockTimer: ReturnType<typeof setInterval> | null = null;
const subscribeClock = (cb: () => void) => {
  clockListeners.add(cb);
  if (!clockTimer) clockTimer = setInterval(() => clockListeners.forEach((l) => l()), 20000);
  return () => {
    clockListeners.delete(cb);
    if (clockListeners.size === 0 && clockTimer) {
      clearInterval(clockTimer);
      clockTimer = null;
    }
  };
};
const readClock = () => Math.floor(Date.now() / 20000);
const readClockServer = () => 0;

export interface SessionCardProps {
  session: VSession;
  prompt?: VPrompt;
  observations: VObservation[];
  /** Session is recording now (isLiveSession) — renders the live variant. */
  live?: boolean;
  /** Avatar initial for the prompt label (default "A"). */
  initial?: string;
  /**
   * The rail collapse wrapper finished its 480ms grid-rows
   * transition — TimelineViewer wires this to rail.queueSync so
   * the ruler bands re-measure once the strip is at full height.
   */
  onRailReveal?: () => void;
  /**
   * A stack click-through's target observation is revealed — fired
   * from the same railwrap transitionend once the rail expand
   * settles (or immediately when the rail was already open).
   * TimelineViewer wires this to rail.jumpToObs (center + flash).
   */
  onObsReveal?: (domId: string) => void;
}

const SUMMARY_ROWS = [
  ['learned', 'Learned', '/icon-thick-learned.svg'],
  ['completed', 'Completed', '/icon-thick-completed.svg'],
  ['next_steps', 'Next steps', '/icon-thick-next-steps.svg'],
] as const;

export function SessionCard({
  session,
  prompt,
  observations,
  live = false,
  initial = 'A',
  onRailReveal,
  onObsReveal,
}: SessionCardProps) {
  const hasPrompt = Boolean(prompt?.text);
  const canToggle = session.hasSummary && hasPrompt;
  // newest observation in DOM-id form — the auto-follow target and
  // the pin test (the list arrives time-ascending, groupObsBySession)
  const lastObsDomId = observations.length > 0 ? `obs-${observations[observations.length - 1].id}` : null;
  const [faceChoice, setFaceChoice] = React.useState<'summary' | 'prompt'>('summary');
  // Selection (Phase 2): the observation whose face the head shows,
  // in DOM-id form (`obs-<id>`, matching the rail's id/data-dot
  // attrs) + `follow` — while live, landings keep taking the
  // selection until the user pins an older obs. One state object so
  // the pair updates atomically. A mount mid-recording starts on the
  // newest obs (the same place auto-follow would have landed).
  const [sel, setSel] = React.useState<{ obsId: string | null; follow: boolean }>(() => ({
    obsId: live ? lastObsDomId : null,
    follow: true,
  }));
  // narrative expander on the obs face — reset closed on every
  // selection change (in the event handlers and the guarded render-
  // time blocks below, never in an effect)
  const [narrOpen, setNarrOpen] = React.useState(false);
  // live auto-follow (Phase 3): when the newest obs id changes while
  // recording with follow on, the landing takes the selection — the
  // first one swaps the full-size prompt to the obs face (the prompt
  // "shrinks" to the minprompt row), later ones advance the ring.
  // Derived-state-from-props: setState during render behind a
  // prev-value guard (the prevLive idiom below) — no effects, no
  // timers. TimelineViewer's landing effect independently runs
  // rail.landObs for the tcCardLand + delayed tcFlash.
  const [prevLastObsId, setPrevLastObsId] = React.useState(lastObsDomId);
  if (lastObsDomId !== prevLastObsId) {
    setPrevLastObsId(lastObsDomId);
    if (live && sel.follow && lastObsDomId) {
      setSel({ obsId: lastObsDomId, follow: true });
      setNarrOpen(false);
    }
  }
  // Resolve the selection against the rendered observations — a
  // dangling id (obs filtered away) simply falls back to the
  // Phase 1 faces.
  const selectedObs = sel.obsId ? observations.find((o) => `obs-${o.id}` === sel.obsId) : undefined;
  // Effective face: a selected obs wins; else no summary → permanent
  // prompt face; summary without a prompt → permanent summary face;
  // otherwise the seg control's choice.
  const face: 'summary' | 'prompt' | 'obs' = selectedObs
    ? 'obs'
    : session.hasSummary
      ? canToggle
        ? faceChoice
        : 'summary'
      : 'prompt';

  // A stack-click jump parked for the rail expand (see selectFromStack).
  // Any other selection change invalidates it — card/dot/deselect
  // handlers clear the ref so a mid-expand click can't center+flash a
  // stale target once the expand's transitionend fires.
  const pendingJumpRef = React.useRef<string | null>(null);

  // deselect → land on the given face (seg buttons / shrunken prompt
  // row). No-summary sessions derive 'prompt' regardless of choice.
  const deselectTo = (choice: 'summary' | 'prompt') => {
    pendingJumpRef.current = null;
    setSel((prev) => (prev.obsId === null && prev.follow ? prev : { obsId: null, follow: true }));
    setNarrOpen(false);
    if (canToggle) setFaceChoice(choice);
  };
  // obs-card click: toggle — re-clicking the selected card deselects
  // (back to the Phase 1 face). No jump: the card is already in view.
  // follow derives from the click target (Phase 3 manual pin): a
  // non-newest obs pins the selection against future landings; the
  // newest obs (or a deselect) resumes following.
  const selectFromCard = (domId: string) => {
    pendingJumpRef.current = null;
    setNarrOpen(false);
    setSel((prev) =>
      prev.obsId === domId ? { obsId: null, follow: true } : { obsId: domId, follow: domId === lastObsDomId },
    );
  };
  // ruler-dot click: select only — the doc-delegated [data-dot]
  // handler (useRailSync 280–284) already centers + flashes, so no
  // rail.jumpToObs here (it would double-jump).
  const selectFromDot = (domId: string) => {
    if (sel.obsId !== domId) {
      pendingJumpRef.current = null;
      setNarrOpen(false);
      setSel({ obsId: domId, follow: domId === lastObsDomId });
    }
  };
  // stack click (Phase 4): select the type's EARLIEST obs. The face
  // change collapses the summary body and expands the rail (480ms
  // grid-rows); the center+flash jump waits for that expand — the
  // domId parks in a ref (no re-render needed) and the railwrap
  // transitionend below fires onObsReveal, replacing the design's
  // 540ms altGoToObs timer (dc.html 1774–1777) with the actual
  // transition boundary. Stacks only render on the summary face
  // (rail collapsed), but if the rail is somehow already open the
  // jump fires immediately instead. follow mirrors selectFromCard:
  // only the session's newest obs keeps following.
  const selectFromStack = (domId: string) => {
    setNarrOpen(false);
    setSel({ obsId: domId, follow: domId === lastObsDomId });
    if (face !== 'summary') onObsReveal?.(domId);
    else pendingJumpRef.current = domId;
  };

  // 20s-quantized wall clock — 0 on the server; every card re-renders
  // together on the shared tick (cheap; display times are minute-level)
  const nowSec = React.useSyncExternalStore(subscribeClock, readClock, readClockServer) * 20;

  // live→wrapped transition (Phase 3 wrap): when the summary rolls
  // in, clear the selection (follow back on), land the butter summary
  // face with tcFadeUp (design 726), and close the narrative. A
  // live→false WITHOUT a summary keeps the selection — the card
  // settles on its last obs face (plan mapping decision #6).
  // Derived-state-from-props pattern — adjust during render, no
  // effects.
  const [prevLive, setPrevLive] = React.useState(live);
  const [heroLanded, setHeroLanded] = React.useState(false);
  if (live !== prevLive) {
    setPrevLive(live);
    if (!live && session.hasSummary) {
      setHeroLanded(true);
      setSel({ obsId: null, follow: true });
      setNarrOpen(false);
      if (canToggle) setFaceChoice('summary');
    }
  }

  // distilling window (Phase 3): freshly wrapped without a summary —
  // the head shows the spinner pill for 5 minutes past `ended`,
  // ticked by the shared 20s clock (no new timers). nowSec is 0 on
  // the server, where the settled region renders instead.
  const distilling = !live && !session.hasSummary && nowSec > 0 && nowSec - session.ended < 300;

  // live window extends outward to now, so the playhead and late
  // observations always fit; rulerWindow re-grids only when now
  // crosses the rounded edge (plan Phase 4 item 2).
  const win = rulerWindow(session.started, live ? Math.max(session.ended, nowSec) : session.ended);
  const playFrac = live && nowSec > 0 ? fracFor(nowSec, win) : null;
  const promptHeadline = prompt?.text || session.request;
  const rows = SUMMARY_ROWS.filter(([key]) => Boolean(session[key]));

  // type stacks (Phase 4, dc.html 444–521): per-type counts for the
  // summary face's stack index — TYPE_META key order first, unknown
  // types trailing in first-seen order (their chips fall back to the
  // same neutral canvas/ink-2 ObsCard and Ruler use). Each stack
  // remembers its EARLIEST observation (min `at`) as the click-
  // through target. Only summarized sessions have a summary face,
  // so others skip the aggregation entirely.
  const stacks: { type: string; count: number; firstDomId: string }[] = [];
  if (session.hasSummary && observations.length > 0) {
    const byType = new Map<string, { count: number; earliest: VObservation }>();
    for (const o of observations) {
      const entry = byType.get(o.type);
      if (!entry) byType.set(o.type, { count: 1, earliest: o });
      else {
        entry.count += 1;
        if (o.at < entry.earliest.at) entry.earliest = o;
      }
    }
    const ordered = [
      ...Object.keys(TYPE_META).filter((t) => byType.has(t)),
      ...[...byType.keys()].filter((t) => !Object.hasOwn(TYPE_META, t)),
    ];
    for (const t of ordered) {
      const entry = byType.get(t);
      if (entry) stacks.push({ type: t, count: entry.count, firstDomId: `obs-${entry.earliest.id}` });
    }
  }
  const selMeta = selectedObs ? TYPE_META[selectedObs.type] : undefined;
  const SelIcon = selMeta?.icon;

  // rail visibility: expanded off the summary face (prompt face, and
  // always for no-summary sessions); collapsed while the summary face
  // shows (the alt design treats the summary as the index).
  const railOpen = face !== 'summary';
  const showRail = observations.length > 0 || !session.hasSummary;

  const summaryLabel = (
    <>
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img src="/icon-thick-completed.svg" alt="" className="tcv-sumicon" />
      <span className="tcv-sumlabel">Session summary</span>
    </>
  );
  const promptLabel = (
    <>
      <span className="tcv-avatar20">{initial}</span>
      <span className="tcv-promptwhen">prompt · {fmtTime(prompt?.at ?? session.started)}</span>
    </>
  );

  return (
    <section id={`sess-${session.id}`} className="tcv-session" data-live={live || undefined}>
      {/* tinted head — the single face surface (dc.html 378–441) */}
      <div
        data-m="tinthead"
        className={heroLanded ? 'tcv-tinthead tcv-hero--landed' : 'tcv-tinthead'}
        data-face={face}
      >
        <span className="tcv-heroarc tcv-heroarc1" />
        <span className="tcv-heroarc tcv-heroarc2" />
        <div className="tcv-herocol">
          {/* head row — label stack + state region (dc.html 382–422) */}
          <div data-m="althead" className="tcv-herohead">
            <span className="tcv-herostack">
              {canToggle ? (
                <>
                  <span data-fade="summary">{summaryLabel}</span>
                  <span data-fade="prompt">{promptLabel}</span>
                </>
              ) : (
                <span data-fade={session.hasSummary ? 'summary' : 'prompt'}>
                  {session.hasSummary ? summaryLabel : promptLabel}
                </span>
              )}
              {/* shrunken prompt row — obs face only (plan Phase 2 item 2):
                  avatar + 1-line-clamped quote + `prompt · time`; click
                  returns to the prompt face */}
              {hasPrompt && (
                <span
                  data-fade="obs"
                  role="button"
                  aria-label="Back to prompt"
                  aria-hidden={face !== 'obs' || undefined}
                  tabIndex={face === 'obs' ? 0 : -1}
                  className="tcv-minprompt"
                  onClick={() => deselectTo('prompt')}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      e.preventDefault();
                      deselectTo('prompt');
                    }
                  }}
                >
                  <span className="tcv-avatar20">{initial}</span>
                  <span className="tcv-minquote">“{prompt?.text}”</span>
                  <span className="tcv-promptwhen">prompt · {fmtTime(prompt?.at ?? session.started)}</span>
                </span>
              )}
            </span>
            {live ? (
              // streaming region (dc.html 394–403): eye counter — hidden
              // until any observations exist — + the Recording pill
              // (mint/jade, pulsing 7×7 dot). No fabricated tool counts.
              <>
                {observations.length > 0 && (
                  <span className="tcv-liveobs" data-tip="Observations distilled so far" data-tip-pos="above">
                    <Eye size={11} strokeWidth={2} />
                    {observations.length} observation{observations.length === 1 ? '' : 's'}
                  </span>
                )}
                <span className="tcv-livepill">
                  <span className="tcv-livepilldot" />
                  Recording
                </span>
              </>
            ) : distilling ? (
              // distilling region (dc.html 404–410): time-range + spinner
              // pill with the real observation count.
              <>
                <span className="tcv-prange">{fmtTimeRange(session.started, session.ended)}</span>
                <span className="tcv-distillpill">
                  <span className="tcv-distillspin" />
                  <span className="tcv-distilllabel">
                    distilling {observations.length} observation{observations.length === 1 ? '' : 's'}…
                  </span>
                </span>
              </>
            ) : (
              // settled region (dc.html 411–422, Replay omitted) — the old
              // prompt-row time-range + badge meta lives here now.
              <>
                <span className="tcv-prange">{fmtTimeRange(session.started, session.ended)}</span>
                <span className="tcv-badge">
                  {observations.length} observation{observations.length === 1 ? '' : 's'}
                </span>
                {canToggle && (
                  // on the obs face both buttons render unpressed;
                  // clicking either deselects and lands on that face
                  <div role="group" aria-label="Show summary or prompt" className="tcv-seg">
                    <button
                      type="button"
                      aria-pressed={face === 'summary'}
                      className={face === 'summary' ? 'tcv-seg-on' : undefined}
                      onClick={() => deselectTo('summary')}
                    >
                      Summary
                    </button>
                    <button
                      type="button"
                      aria-pressed={face === 'prompt'}
                      className={face === 'prompt' ? 'tcv-seg-on' : undefined}
                      onClick={() => deselectTo('prompt')}
                    >
                      Prompt
                    </button>
                  </div>
                )}
              </>
            )}
          </div>

          {/* title cross-fade (dc.html 424–426) — the obs title takes
              the same 20px/600/1.32 slot on the obs face */}
          {(session.hasSummary || Boolean(promptHeadline) || selectedObs) && (
            <div className="tcv-heroheadline">
              {session.hasSummary && <h2 data-fade="summary">{session.request}</h2>}
              {(canToggle || (!session.hasSummary && Boolean(promptHeadline))) && (
                <p data-fade="prompt">“{promptHeadline}”</p>
              )}
              {selectedObs && <h2 data-fade="obs">{selectedObs.title}</h2>}
            </div>
          )}

          {/* obs meta row — type chip + label + time + #id (obs face only) */}
          {selectedObs && (
            <div className="tcv-obsmeta">
              <span
                className="tcv-obschip"
                style={{ background: selMeta?.chip ?? 'var(--canvas)', color: selMeta?.fg ?? 'var(--ink-2)' }}
              >
                {SelIcon ? <SelIcon size={13} strokeWidth={2} /> : null}
              </span>
              <span className="tcv-obstype" style={{ color: selMeta?.fg ?? 'var(--ink-2)' }}>
                {selectedObs.type}
              </span>
              <span className="tcv-prange">{fmtTime(selectedObs.at)}</span>
              <span className="tcv-obsid">#{selectedObs.id}</span>
            </div>
          )}

          {/* collapsing body — grid-rows 1fr/0fr (dc.html 428–441).
              Expanded on the summary AND obs faces; one slot, two
              contents: summary rows vs. facts + narrative expander. */}
          {(rows.length > 0 || observations.length > 0) && (
            <div className="tcv-herobodywrap">
              <div className="tcv-herobodyclip">
                {selectedObs ? (
                  <div className="tcv-obsbody">
                    {selectedObs.facts.length > 0 && (
                      <div className="tcv-obsfacts">
                        {selectedObs.facts.map((fact, i) => (
                          <div key={i} className="tcv-obsfact">
                            <span />
                            <p>{fact}</p>
                          </div>
                        ))}
                      </div>
                    )}
                    {selectedObs.narrative && (
                      <>
                        <button
                          type="button"
                          className="tcv-narrbtn"
                          aria-expanded={narrOpen}
                          onClick={() => setNarrOpen((o) => !o)}
                        >
                          <ChevronDown size={11} strokeWidth={2} />
                          narrative
                        </button>
                        <div className="tcv-narrwrap" data-open={narrOpen || undefined}>
                          <div className="tcv-narrclip">
                            <p className="tcv-narrtext">{selectedObs.narrative}</p>
                          </div>
                        </div>
                      </>
                    )}
                  </div>
                ) : (
                  <>
                    {rows.length > 0 && (
                      <div className="tcv-herorows">
                        {rows.map(([key, label, icon]) => (
                          <div key={key} className="tcv-herorow">
                            {/* eslint-disable-next-line @next/next/no-img-element */}
                            <img src={icon} alt="" />
                            <p>
                              <b>{label}</b>
                              {' — '}
                              {session[key]}
                            </p>
                          </div>
                        ))}
                      </div>
                    )}
                    {/* type stacks (dc.html 444–521) — summary-face
                        observation index; back "paper" layer at
                        count ≥ 2; click/Enter/Space jumps to the
                        type's earliest obs after the rail expands */}
                    {stacks.length > 0 && (
                      <div className="tcv-stacks">
                        {stacks.map(({ type, count, firstDomId }) => {
                          const meta = TYPE_META[type];
                          const StackIcon = meta?.icon;
                          const tip = `See the ${count} ${type} card${count === 1 ? '' : 's'} in the timeline`;
                          return (
                            <div
                              key={type}
                              role="button"
                              tabIndex={0}
                              aria-label={tip}
                              className="tcv-stack"
                              data-tip={tip}
                              data-tip-pos="above"
                              onClick={() => selectFromStack(firstDomId)}
                              onKeyDown={(e) => {
                                if (e.key === 'Enter' || e.key === ' ') {
                                  e.preventDefault();
                                  selectFromStack(firstDomId);
                                }
                              }}
                            >
                              {count >= 2 && <span className="tcv-stackback" />}
                              <span className="tcv-stackfront">
                                <span className="tcv-stackhead">
                                  <span
                                    className="tcv-obschip"
                                    style={{
                                      background: meta?.chip ?? 'var(--canvas)',
                                      color: meta?.fg ?? 'var(--ink-2)',
                                    }}
                                  >
                                    {StackIcon ? <StackIcon size={13} strokeWidth={2} /> : null}
                                  </span>
                                  <span className="tcv-obstype" style={{ color: meta?.fg ?? 'var(--ink-2)' }}>
                                    {type}
                                  </span>
                                </span>
                                <span className="tcv-stackcount">
                                  <b>{count}</b>
                                  <span>card{count === 1 ? '' : 's'}</span>
                                </span>
                              </span>
                            </div>
                          );
                        })}
                      </div>
                    )}
                  </>
                )}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* rail — natural order, wrapped in the grid-rows collapse pair
          (dc.html 561–563); omitted for wrapped sessions with no
          observations. */}
      {showRail && (
        <div
          className="tcv-railwrap"
          data-open={railOpen || undefined}
          onTransitionEnd={(e) => {
            if (e.target !== e.currentTarget || e.propertyName !== 'grid-template-rows') return;
            onRailReveal?.();
            // pending stack jump (Phase 4): center + flash only once
            // the EXPAND settles; a collapse ending here (deselected
            // mid-flight) just clears the stale target.
            const pending = pendingJumpRef.current;
            if (pending) {
              pendingJumpRef.current = null;
              if (railOpen) onObsReveal?.(pending);
            }
          }}
        >
          <div className="tcv-railclip">
            <div data-rail={session.id} className="tcv-rail">
              <Ruler
                win={win}
                observations={observations}
                playFrac={playFrac}
                selectedObsId={sel.obsId}
                onSelectObs={selectFromDot}
              />
              <Strip
                observations={observations}
                win={win}
                live={live}
                selectedObsId={sel.obsId}
                onSelectObs={selectFromCard}
              />
            </div>
          </div>
        </div>
      )}
    </section>
  );
}

