// ============================================================
// cmem timeline viewer — ask-your-memory engine (Phase 4).
//
// The scoring/synthesis block (STOPWORDS … synthesizeAnswer) is
// ported VERBATIM from the old viewer's SearchAgent.tsx:26–134 —
// an instant local recall + compose over the user's own loaded
// observations. Do not "improve" the scoring here.
//
// runAskStaged() restages that engine to the Timeline Cards
// choreography (timeline-cards.dc.html runAsk 1990–2051):
// step labels/timings are the design's, counts are real. One
// deliberate deviation from the old viewer: the trailing 'cite'
// block never renders in the thread body — citations feed the
// ask card's side rail only (DESIGN-SPEC §5), and the no-match
// copy is the design's (dc 1965–1972) with real counts instead
// of the old viewer's concept-chip copy (plan Phase 4 item 1).
// ============================================================
import type { NoteBlock, ViewerData, VObservation } from './types';

import { fmtDayLabel, fmtTime } from './format';

// ---------- ported verbatim from SearchAgent.tsx:26–134 ----------

const STOPWORDS = new Set(['the', 'a', 'an', 'and', 'or', 'for', 'with', 'how', 'what', 'why', 'does', 'did', 'is', 'are', 'was', 'were', 'do', 'we', 'our', 'you', 'your', 'when', 'where', 'that', 'this', 'about', 'work', 'works']);

function tokenize(q: string): string[] {
  return q.toLowerCase().split(/[^a-z0-9-]+/).filter((t) => t.length > 2 && !STOPWORDS.has(t));
}

function scoreText(tokens: string[], text: string, weight: number): number {
  if (!text) return 0;
  const lower = text.toLowerCase();
  let s = 0;
  tokens.forEach((t) => { if (lower.includes(t)) s += weight; });
  return s;
}

function scoreObservation(tokens: string[], o: VObservation): number {
  return scoreText(tokens, o.title, 3)
    + scoreText(tokens, (o.concepts || []).join(' '), 3)
    + scoreText(tokens, o.subtitle, 2)
    + scoreText(tokens, (o.facts || []).join(' '), 2)
    + scoreText(tokens, o.narrative, 1)
    + scoreText(tokens, (o.files_read || []).concat(o.files_modified || []).join(' '), 2);
}

export interface SearchResult {
  observations: VObservation[];
  files: [string, number][];
  concepts: string[];
}

// Instant string-match search across the loaded memories
export function searchMemory(query: string, data: ViewerData): SearchResult {
  const tokens = tokenize(query);
  const raw = query.trim().toLowerCase();
  if (!raw) return { observations: [], files: [], concepts: [] };

  const scored = data.observations
    .map((o) => ({ o, s: scoreObservation(tokens.length ? tokens : [raw], o) }))

