'use client';

// ============================================================
// cmem timeline viewer — observation card (Phase 2b).
// Anatomy from timeline-cards.dc.html 970–978 (canonical obs
// card): 22×22 r8 type chip + type label + mono time, 3-line
// clamped title, mono #id. `data-at` carries the observation's
// time fraction within the session's ruler window; Phase 3's
// rail sync reads it. Hover lift lives in cards.css.
// Selection (alt-card Phase 2): clicking (or Enter/Space) fires
// onSelect — SessionCard swaps its tinted head to this obs;
// `data-selected` draws the accent ring (separate from the
// data-hot hover-affinity attribute useRailSync owns).
// ============================================================
import type { VObservation } from './types';

import { TYPE_META, fmtTime } from './format';
import { fracFor, type RulerWindow } from './timeline-data';

export interface ObsCardProps {
  obs: VObservation;
  win: RulerWindow;
  /** This card is the session's selected observation (obs face). */
  selected?: boolean;
  /** Click / Enter / Space — SessionCard toggles selection. */
  onSelect?: () => void;
}

export function ObsCard({ obs, win, selected = false, onSelect }: ObsCardProps) {
  const meta = TYPE_META[obs.type];
  const Icon = meta?.icon;
  return (
    <article
      id={`obs-${obs.id}`}
      data-at={fracFor(obs.at, win).toFixed(3)}
      data-obs-type={obs.type}
      data-selected={selected || undefined}
      title={obs.title}
      className="tcv-obscard"
      role="button"
      tabIndex={0}
      onClick={onSelect}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onSelect?.();
        }
      }}
      // stamp the finished land entrance (live sessions) so the CSS
      // rule `.tcv-session[data-live] .tcv-obscard:not([data-landed])`
      // can't replay tcCardLand when useRailSync's flash cleanup later
      // clears the card's inline `animation`. React never renders this
      // attribute, so it survives re-renders; a genuinely new card is
      // a fresh DOM node without it and still animates.
      onAnimationEnd={(e) => {
        if (e.animationName === 'tcCardLand') e.currentTarget.setAttribute('data-landed', '');
      }}
    >
      <div className="tcv-obshead">
        <span
          className="tcv-obschip"
          style={{ background: meta?.chip ?? 'var(--canvas)', color: meta?.fg ?? 'var(--ink-2)' }}
        >
          {Icon ? <Icon size={13} strokeWidth={2} /> : null}
        </span>
        <span className="tcv-obstype" style={{ color: meta?.fg ?? 'var(--ink-2)' }}>
          {obs.type}
        </span>
        <span className="tcv-obstime">{fmtTime(obs.at)}</span>
      </div>
      <p className="tcv-obstitle">{obs.title}</p>
      <span className="tcv-obsid">#{obs.id}</span>
    </article>
  );
}

