// Phase 2 verification — ✦ distill button + panel (real synthesis).
// Runs against http://localhost:3005/dev/viewer-preview (fixture).
import { chromium, devices } from 'playwright';

const OUT = '/private/tmp/claude-501/-Users-user-Scripts-claude-mem-pro/098c27bd-a3aa-4082-8462-a9ebe76025f2/scratchpad/verify';
const BASE = 'http://localhost:3005/dev/viewer-preview';

const results = [];
const check = (name, pass, detail) => {
  results.push({ name, pass, detail });
  console.log(`${pass ? 'PASS' : 'FAIL'}  ${name} — ${detail}`);
};

const consoleIssues = [];
const browser = await chromium.launch({ channel: 'chrome', headless: true });
const trackConsole = (page, label) => {
  page.on('console', (m) => {
    if (m.type() === 'error' || m.type() === 'warning') {
      consoleIssues.push({ label, kind: m.type(), text: m.text() });
      console.log(`[console.${m.type()}] (${label})`, m.text());
    }
  });
  page.on('pageerror', (e) => {
    consoleIssues.push({ label, kind: 'pageerror', text: e.message });
    console.log(`[pageerror] (${label})`, e.message);
  });
};

const gotoFresh = async (p, url = BASE) => {
  await p.goto(url, { waitUntil: 'networkidle', timeout: 60000 });
  await p.waitForSelector('.tcv-tinthead', { timeout: 15000 });
  await p.waitForTimeout(600);
};

const S1 = '#sess-s1';
const s1state = (p) =>
  p.evaluate(() => {
    const sec = document.getElementById('sess-s1');
    const wrap = sec.querySelector('.tcv-magicwrap');
    return {
      face: sec.querySelector('.tcv-tinthead').getAttribute('data-face'),
      wrapOpen: wrap ? wrap.hasAttribute('data-open') : null,
      wrapExists: !!wrap,
      run: sec.querySelector('.tcv-magicrun')?.textContent.trim() ?? null,
      label: sec.querySelector('.tcv-magiclabel')?.textContent.trim() ?? null,
      meta: sec.querySelector('.tcv-magicmeta')?.textContent.trim() ?? null,
      text: sec.querySelector('.tcv-magictext')?.textContent.trim() ?? null,
      chips: [...sec.querySelectorAll('.tcv-citechip')].map((c) => c.textContent.trim()),
      selected: sec.querySelectorAll('[data-selected]').length,
      replaying: sec.hasAttribute('data-replaying'),
      railOpen: sec.querySelector('.tcv-railwrap')?.hasAttribute('data-open') ?? null,
    };
  });

// ============ main context (light desktop) ============
const page = await browser.newPage({ viewport: { width: 1600, height: 1000 }, deviceScaleFactor: 2 });
trackConsole(page, 'desktop-light');
await gotoFresh(page);

// --- 1. reveal ---
const stackSel = `${S1} .tcv-stack[data-stack]`;
const magicSel = `${stackSel} .tcv-magic`;
const discoStack = page.locator(stackSel).first(); // stacks ordered by TYPE_META: discovery first
const magicBtn = page.locator(magicSel).first();
const opBefore = await magicBtn.evaluate((el) => getComputedStyle(el).opacity);
await discoStack.hover();
await page.waitForTimeout(300);
const opHover = await magicBtn.evaluate((el) => ({ op: getComputedStyle(el).opacity, tf: getComputedStyle(el).transform }));
check('1. reveal on hover', opBefore === '0' && opHover.op === '1', `opacity ${opBefore} -> ${opHover.op}, transform ${opHover.tf}`);
await magicBtn.screenshot({ path: `${OUT}/phase2v-reveal.png` }).catch(() => {});
await discoStack.screenshot({ path: `${OUT}/phase2v-reveal-stack.png` }).catch(() => {});
// focus reveal
await page.mouse.move(10, 10);
await page.waitForTimeout(250);
await discoStack.evaluate((el) => el.focus());
await page.waitForTimeout(250);
const opFocus = await magicBtn.evaluate((el) => getComputedStyle(el).opacity);
check('1b. reveal on focus-within', opFocus === '1', `opacity ${opFocus} while stack focused`);

// --- 2. open -> running ---
await discoStack.hover();
await magicBtn.click();
await page.waitForTimeout(200);
let st = await s1state(page);
check(
  '2. running state',
  st.wrapOpen === true && st.run === 'distilling 2 observations…' && st.face === 'summary' && st.selected === 0,
  `open=${st.wrapOpen} run="${st.run}" face=${st.face} selected=${st.selected}`,
);

// --- 3. done state ---
await page.waitForTimeout(1400);
st = await s1state(page);
const chipsOk = st.chips.length === 2 && st.chips[0].startsWith('#101258') && st.chips[1].startsWith('#101259');
check(
  '3. done state',
  st.label === 'Discoveries, distilled' &&
    st.meta === '2 observations' &&
    (st.text || '').includes('14 prior sessions') &&
    (st.text || '').includes('VObservation join') &&
    chipsOk,
  `label="${st.label}" meta="${st.meta}" chips=${JSON.stringify(st.chips)} text="${(st.text || '').slice(0, 90)}…"`,
);
await page.locator(`${S1} .tcv-magicpanel`).screenshot({ path: `${OUT}/phase2v-panel-light.png` }).catch(() => {});

// --- 5a. persistence across face flips ---
await page.locator(`${S1} .tcv-seg button`, { hasText: 'Prompt' }).click();
await page.waitForTimeout(700);
const facePrompt = (await s1state(page)).face;
await page.locator(`${S1} .tcv-seg button`, { hasText: 'Summary' }).click();
await page.waitForTimeout(700);
st = await s1state(page);
check(
  '5a. persists across face flip',
  facePrompt === 'prompt' && st.wrapOpen === true && st.label === 'Discoveries, distilled',
  `prompt face=${facePrompt}, back-open=${st.wrapOpen}, label="${st.label}"`,
);

// --- 4. cite jump ---
await page.locator(`${S1} .tcv-citechip`, { hasText: '#101259' }).click();
await page.waitForTimeout(900); // 480ms expand + jump
st = await s1state(page);
const jump = await page.evaluate(() => {
  const sec = document.getElementById('sess-s1');
  const card = document.getElementById('obs-101259');
  const strip = sec.querySelector('[data-strip]');
  const cr = card.getBoundingClientRect();
  const sr = strip.getBoundingClientRect();
  return {
    sel: card.hasAttribute('data-selected'),
    anim: card.style.animation || '',
    centerDelta: Math.round(cr.left + cr.width / 2 - (sr.left + sr.width / 2)),
    title: sec.querySelector('.tcv-heroheadline h2[data-fade="obs"]')?.textContent ?? '',
  };
});
// flash may take a moment; poll briefly if not yet inline
let flashSeen = jump.anim.includes('tcFlash');
for (let i = 0; i < 10 && !flashSeen; i++) {
  await page.waitForTimeout(150);
  flashSeen = await page.evaluate(() => (document.getElementById('obs-101259').style.animation || '').includes('tcFlash'));
}
check(
  '4. cite jump',
  st.face === 'obs' && st.railOpen === true && jump.sel && Math.abs(jump.centerDelta) < 140 && flashSeen,
  `face=${st.face} railOpen=${st.railOpen} selected=${jump.sel} centerDelta=${jump.centerDelta}px flash=${flashSeen} title="${jump.title.slice(0, 40)}"`,
);

// --- 5b/5c. back to summary, close, switch kind ---
await page.locator(`${S1} .tcv-seg button`, { hasText: 'Summary' }).click();
await page.waitForTimeout(700);
st = await s1state(page);
const stillOpen = st.wrapOpen === true;
await page.locator(`${S1} .tcv-magicclose`).click();
await page.waitForTimeout(500);
st = await s1state(page);
check('5b. close X collapses', stillOpen && st.wrapOpen === false, `open-after-obs-face=${stillOpen}, after-close=${st.wrapOpen}`);
// decision stack ✦ (stack index 1 in TYPE_META order: discovery, decision, …)
const decStack = page.locator(stackSel).nth(1);
await decStack.hover();
await decStack.locator('.tcv-magic').click();
await page.waitForTimeout(150);
const runDec = (await s1state(page)).run;
await page.waitForTimeout(1400);
st = await s1state(page);
check(
  '5c. switch kind',
  runDec === 'distilling 1 observation…' && st.label === 'Decisions, distilled' && st.chips.length === 1,
  `run="${runDec}" label="${st.label}" chips=${st.chips.length}`,
);

// --- 6. s3 cap (discovery ×6) ---
await gotoFresh(page);
const s3stack = page.locator('#sess-s3 .tcv-stack[data-stack]').first();
await s3stack.hover();
await s3stack.locator('.tcv-magic').click();
await page.waitForTimeout(1500);
const s3 = await page.evaluate(() => {
  const sec = document.getElementById('sess-s3');
